INSERT INTO `cms_page` VALUES (1,1,NULL,'<p>\r\n	&nbsp; &nbsp; &nbsp; &nbsp;安阳市卓易机械电子有限公司，致力于振动器的研制与开发，专注于解决物料堵塞的各种问题。专业生产气动振动器、气动敲击锤、电动振动器、电动敲击锤、小型电磁振动器、零速开关、振动器控制箱、电磁阀箱等产品。产品广泛应用于化工、机械、食品、饲料、水泥、制药、矿业等所有加工粉体的行业。</p>\r\n<p>\r\n	&nbsp; &nbsp; &nbsp; &nbsp;公司拥有一支具有丰富的研发和生产经验的技术人员构成的团队，引进国外先进的技术设备、独特的工艺、完善的检测手段和科学的质量控制，结合国内产品需求实情，辅以本厂专业技术人员的精心研发、以满足不同客户的需求，且产品赢得了广大用户的一致好评。产品广泛应用于冶金、化工、环保、建材、火电、矿山、碎石场、机械、选矿、煤炭、食品、水泥、制药、化肥、粮食、铸造、陶瓷、磨料等行业中。</p>\r\n<br>\r\n<h2>\r\n	企业口号：</h2>\r\n<p>\r\n	以高品质的产品和服务为客户创造价值，绝不为短期的利益而出卖未来！</p>\r\n<h2>\r\n	企业目标：</h2>\r\n<p>\r\n	打造振动器行业知名品牌</p>\r\n<h2>\r\n	企业理念：</h2>\r\n<p>\r\n	质量铸就品牌，服务立足市场。</p>\r\n<br>\r\n<h2>\r\n	公司荣誉</h2>\r\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n				<img height=\"80\" src=\"/upfile/2025/01/1737169923359.jpg\" width=\"127\" alt=\"zhengshu3.jpg\"></td>\r\n			<td style=\"padding-left:20px\">\r\n				<h3>\r\n					质量达标，放心品牌</h3>\r\n<p>\r\n					经过多年孜孜不倦的设计追求与产品改进，我公司生产的数款振动器产品于2011年经国家权威检测，被定为质量达标、放心品牌，从而为公司的产品销售打开并提供了强有力的支撑与支持！</p>\r\n</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br>\r\n<br>\r\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\r\n	<tbody>\r\n		<tr>\r\n			<td>\r\n				<img height=\"80\" src=\"/upfile/2025/01/1737169934799.jpg\" width=\"127\" alt=\"zhengshu1.jpg\"></td>\r\n			<td style=\"padding-left:20px\">\r\n				<h3>\r\n					ISO9001：2000质量管理体系认证证书</h3>\r\n<p>\r\n					我司于2013年4月通过中国检验认证集团质量认证有限公司认证，取得了ISO9001:2000质量管理体系认证证书！从而更加完善我司内部组织管理，提高产品质量与竞争力，也为我司更好地与国际接轨，向海外进军...</p>\r\n</td>\r\n		</tr>\r\n	</tbody>\r\n</table>\r\n<br>\r\n<img src=\"/upfile/2025/01/1737169941964.png\" width=\"100%\" alt=\"cerz.png\">'),(2,5,NULL,'<p>\r\n	<span style=\"font-size:16px;\"><strong style=\"color:#c00\">企业宗旨：</strong></span>诚信为本 质量为上</p>\r\n<p>\r\n	<strong style=\"color:#c00\"><span style=\"font-size:16px;\">经营信条：</span></strong>铸卓易品牌 让用户满意 是我们永恒的追求</p>\r\n<p>\r\n	<strong style=\"color:#c00\"><span style=\"font-size:16px;\">服务宗旨：</span></strong>对每一道工序负责 对每一台产品负责 对每一位用户负责</p>\r\n<span style=\"font-size:16px;\"><strong style=\"color:#c00\">服务理念：</strong></span>\r\n<p>\r\n	卓易机械以精湛的工艺和先进技术水平赢得了许多荣誉，卓易机械更是视质量为生命，奉用户为上帝。用户就是我们的一切。我们将会一直遵循对每一道工序负责、对每一台产品负责、对每一位用户负责的质量方针，竭诚为用户服务。我们所做的一切将全力为您着想。我们深信：对您奉献一颗真诚的心同样会得到真诚的回报！</p>\r\n<p>\r\n	卓易员工已经树立了良好的服务理念：用户设备发生故障时的及时维修；售前为用户提供项目设计、工艺流程设计；用户的设备选购方案制定；优质的产品提供；耐心周到的用户培训；及时有效的故障维修以及代为用户试验解决疑难加工问题等。</p>\r\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td class=\"\">\r\n				<br>\r\n				<span style=\"font-size:16px;\"><strong style=\"color:#c00\">服务承诺</strong></span><br>\r\n<p style=\"line-height:26px;\">\r\n					&nbsp; &nbsp;<img height=\"6\" src=\"/upfile/2025/01/1737169889933.gif\" width=\"9\" alt=\"gif-01.gif\">&nbsp;售前服务：为您提供项目设计、工艺流程设计，适合您的机器设备选购方案的制定，根据您的特殊需求，设计制造产品，为您培训技术操作人员。<br>\r\n					&nbsp;&nbsp;&nbsp;<img height=\"6\" src=\"/upfile/2025/01/1737169889933.gif\" width=\"9\">&nbsp;售中服务：陪您一起完成对设备的验收，协助拟订施工方案和详细流程。<br>\r\n					&nbsp;&nbsp;&nbsp;<img height=\"6\" src=\"/upfile/2025/01/1737169889933.gif\" width=\"9\">&nbsp;售后服务：公司派技术人员到现场指导设备安装、调试现场及培训操作人员。</p>\r\n</td>\r\n			<td class=\"\">\r\n				<img src=\"/upfile/2025/01/1737169859345.jpg\" alt=\"dp.jpg\"></td>\r\n		</tr>\r\n	</tbody>\r\n</table>');
/*!40000 ALTER TABLE `cms_page` ENABLE KEYS */;
UNLOCK TABLES;

